frappe.ui.form.on('Plantation Record', {
    onload: function(frm) {
        // Reload options on form load
        if (frm.doc.reporting_division) {
            frm.trigger('reporting_division');
        }
        if (frm.doc.reporting_district) {
            frm.trigger('reporting_district');
        }
    },
    reporting_division: function(frm) {
        if (frm.doc.reporting_division) {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Township Data',
                    filters: {
                        burmese_region_name: frm.doc.reporting_division,
                    },
                    fields: ['burmese_district_name'],
                    distinct: true,
                },
                callback: function(r) {
                    if (r.message) {
                        const district_options = [...new Set(r.message.map(d => d.burmese_district_name))]
                            .sort((a, b) => a.localeCompare(b, 'my'));
                        frm.set_df_property('reporting_district', 'options', district_options.join('\n'));
                        frm.refresh_field('reporting_district');
                    }
                },
            });
        }
    },
    reporting_district: function(frm) {
        if (frm.doc.reporting_district) {
            frappe.call({
                method: 'frappe.client.get_list',
                args: {
                    doctype: 'Township Data',
                    filters: {
                        burmese_district_name: frm.doc.reporting_district,
                    },
                    fields: ['burmese_township_name'],
                    distinct: true,
                },
                callback: function(r) {
                    if (r.message) {
                        const township_options = [...new Set(r.message.map(t => t.burmese_township_name))]
                            .sort((a, b) => a.localeCompare(b, 'my'));
                        frm.set_df_property('township', 'options', township_options.join('\n'));
                        frm.refresh_field('township');
                    }
                },
            });
        }
    },
});

// Doctype: Plantation Record
frappe.ui.form.on('Plantation Record', {
  onload(frm) {
    // Lazy-load mgrs.js
    if (typeof mgrs === 'undefined' && !document.getElementById('mgrs-js')) {
      const s = document.createElement('script');
      s.src = '/assets/plantation_management/js/mgrs.min.js'; // your path
      s.id = 'mgrs-js';
      s.onload = () => {
        console.log('mgrs.js loaded');
        // If user already filled anything, recompute now (acts like a blur-normalize)
        if (frm && frm.doc) {
          if (frm.doc.latitude && frm.doc.longitude) {
            syncFromLatLng(frm);
          } else if (frm.doc.mgrs) {
            syncFromMGRS(frm);
          }
        }
      };
      s.onerror = () => frappe.msgprint(__('Failed to load mgrs.js'));
      document.head.appendChild(s);
    }
  },

  refresh(frm) {
    // Bind blur handlers each refresh (safe: namespaced + off first)
    bind_blur_handlers(frm);

    // If prefilled (e.g., opening existing doc), normalize once
    if (!frm.__coord_initialized) {
      frm.__coord_initialized = true;
      if (frm.doc.latitude && frm.doc.longitude) {
        syncFromLatLng(frm);
      } else if (frm.doc.mgrs) {
        syncFromMGRS(frm);
      }
    }
  },

  validate(frm) {
    // Final cleanup before save (acts like a guaranteed blur)
    normalizeAll(frm);
  }
});

/* =============== Blur binding =============== */

function bind_blur_handlers(frm) {
  // Latitude
  const latField = frm.fields_dict['latitude'];
  if (latField && latField.$input) {
    latField.$input.off('blur.dms_lat').on('blur.dms_lat', () => {
      if (!frm.__coord_updating) syncFromLatLng(frm);
    });
  }

  // Longitude
  const lonField = frm.fields_dict['longitude'];
  if (lonField && lonField.$input) {
    lonField.$input.off('blur.dms_lon').on('blur.dms_lon', () => {
      if (!frm.__coord_updating) syncFromLatLng(frm);
    });
  }

  // MGRS
  const mgrsField = frm.fields_dict['mgrs'];
  if (mgrsField && mgrsField.$input) {
    mgrsField.$input.off('blur.dms_mgrs').on('blur.dms_mgrs', () => {
      if (!frm.__coord_updating) syncFromMGRS(frm);
    });
  }
}

/* =============== Utilities =============== */

function setValueQuiet(frm, fieldname, value) {
  frm.__coord_updating = true;
  frm.set_value(fieldname, value);
  frm.__coord_updating = false;
}

function whenMgrsReady(cb, tries = 40) { // ~10s
  if (typeof mgrs !== 'undefined') return cb();
  if (tries <= 0) return;
  setTimeout(() => whenMgrsReady(cb, tries - 1), 250);
}

function noSpace(v)    { return (v || '').toString().replace(/\s+/g, ''); }
function getVal(v)     { return v == null ? '' : String(v); }
function isFiniteStr(v){ return typeof v === 'number' ? isFinite(v) : /^[-+]?\d+(\.\d+)?$/.test(v); }

/* =============== Core flows (run only on blur/validate) =============== */

function syncFromLatLng(frm) {
  const latRaw = noSpace(getVal(frm.doc.latitude));
  const lonRaw = noSpace(getVal(frm.doc.longitude));
  if (!latRaw || !lonRaw) {
    // If one side missing, just clean the edited one
    if (latRaw) setValueQuiet(frm, 'latitude', latRaw);
    if (lonRaw) setValueQuiet(frm, 'longitude', lonRaw);
    return;
  }

  const parsed = parseLatLonFlexible(latRaw, lonRaw);
  if (!parsed) {
    setValueQuiet(frm, 'latitude',  latRaw);
    setValueQuiet(frm, 'longitude', lonRaw);
    return;
  }

  const dmsLat = toDMS(parsed.lat, true);
  const dmsLon = toDMS(parsed.lon, false);
  setValueQuiet(frm, 'latitude',  dmsLat);
  setValueQuiet(frm, 'longitude', dmsLon);

  // Compute MGRS after user leaves the field
  whenMgrsReady(() => {
    const m = safeMgrsForward(parsed.lat, parsed.lon, 3); // 6-digit (~100 m)
    if (m) setValueQuiet(frm, 'mgrs', m);
  });
}

function syncFromMGRS(frm) {
  const mgrsRaw = noSpace(getVal(frm.doc.mgrs)).toUpperCase();
  if (!mgrsRaw) return;

  whenMgrsReady(() => {
    const pt = safeMgrsToPoint(mgrsRaw);
    if (pt) {
      const [lonDec, latDec] = pt;
      setValueQuiet(frm, 'latitude',  toDMS(latDec, true));
      setValueQuiet(frm, 'longitude', toDMS(lonDec, false));
      setValueQuiet(frm, 'mgrs',      mgrsRaw);
    } else {
      setValueQuiet(frm, 'mgrs', mgrsRaw); // keep cleaned value even if invalid
    }
  });
}

function normalizeAll(frm) {
  const lat = noSpace(getVal(frm.doc.latitude));
  const lon = noSpace(getVal(frm.doc.longitude));
  const mg  = noSpace(getVal(frm.doc.mgrs)).toUpperCase();

  if (!lat && !lon && !mg) return;

  if (lat && lon) {
    const parsed = parseLatLonFlexible(lat, lon);
    if (parsed) {
      setValueQuiet(frm, 'latitude',  toDMS(parsed.lat, true));
      setValueQuiet(frm, 'longitude', toDMS(parsed.lon, false));
      whenMgrsReady(() => {
        const m = safeMgrsForward(parsed.lat, parsed.lon, 3);
        if (m) setValueQuiet(frm, 'mgrs', m);
      });
    } else {
      setValueQuiet(frm, 'latitude', lat);
      setValueQuiet(frm, 'longitude', lon);
    }
  } else if (mg) {
    whenMgrsReady(() => {
      const pt = safeMgrsToPoint(mg);
      if (pt) {
        const [lonDec, latDec] = pt;
        setValueQuiet(frm, 'latitude',  toDMS(latDec, true));
        setValueQuiet(frm, 'longitude', toDMS(lonDec, false));
      }
      setValueQuiet(frm, 'mgrs', mg);
    });
  }
}

/* =============== Parsing & formatting =============== */

// Accepts decimal or DMS strings for both fields
function parseLatLonFlexible(latIn, lonIn) {
  try {
    const lat = parseOne(latIn, true);
    const lon = parseOne(lonIn, false);
    if (!isFinite(lat) || !isFinite(lon)) return null;
    if (Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;
    return { lat, lon };
  } catch {
    return null;
  }
}

function parseOne(value, isLat) {
  if (value == null || value === '') return NaN;
  if (isFiniteStr(value)) return parseFloat(value); // decimal degrees
  const d = dmsToDecimal(value, isLat);             // DMS → decimal
  if (d == null) throw new Error('Bad DMS');
  return d;
}

// Robust DMS parser → decimal degrees
function dmsToDecimal(dmsStr, isLat) {
  if (!dmsStr) return null;

  // Canonicalize symbols WITHOUT touching hemisphere letters
  // Replace "deg"/"º"/"°" → "°" only (don't replace 'E'!)
  let s = dmsStr.toUpperCase();
  s = s.replace(/\s+/g, '');
  s = s.replace(/DEG/gi, '°').replace(/º/g, '°');  // "deg" or "º" → "°"
  s = s.replace(/[’']/g, "'");                      // apostrophes
  s = s.replace(/″|”/g, '"');                       // double-primes

  // [opt hem] deg° [opt min]' [opt sec]" [opt hem]
  const re = /^(?:([NSWE]))?(\d+(?:\.\d+)?)°(?:(\d+(?:\.\d+)?))?'?(?:(\d+(?:\.\d+)?))?"?(?:([NSWE]))?$/;
  const m = s.match(re);
  if (!m) return null;

  let hem = (m[1] || m[5] || '').toUpperCase();
  const deg = parseFloat(m[2] || '0');
  const min = parseFloat(m[3] || '0');
  const sec = parseFloat(m[4] || '0');

  if (!hem) hem = isLat ? 'N' : 'E';         // default if hemisphere not provided
  if (min >= 60 || sec >= 60) return null;
  if (isLat && deg > 90) return null;
  if (!isLat && deg > 180) return null;

  let dec = deg + min / 60 + sec / 3600;
  if ((isLat && hem === 'S') || (!isLat && hem === 'W')) dec = -dec;
  return dec;
}

function toDMS(dec, isLat) {
  const hemi = isLat ? (dec >= 0 ? 'N' : 'S') : (dec >= 0 ? 'E' : 'W');
  const abs = Math.abs(dec);
  const deg = Math.floor(abs);
  const minFloat = (abs - deg) * 60;
  const min = Math.floor(minFloat);
  const sec = (minFloat - min) * 60;
  const secFixed = sec.toFixed(2);
  return `${deg}°${String(min).padStart(2, '0')}'${padSec(secFixed)}"${hemi}`;
}

function padSec(secStr) {
  if (!secStr.includes('.')) return secStr.padStart(2, '0');
  const [i, f] = secStr.split('.');
  return `${i.padStart(2, '0')}.${f}`;
}

/* =============== MGRS helpers =============== */

function safeMgrsForward(lat, lon, precision = 3) {
  try {
    // mgrs.forward expects [lon, lat]
    const s = mgrs.forward([lon, lat], precision);
    return noSpace(s).toUpperCase();
  } catch (e) {
    console.error('MGRS forward error', e);
    frappe.msgprint(__('Unable to calculate MGRS from coordinates.'));
    return '';
  }
}

function safeMgrsToPoint(code) {
  try {
    const cleaned = noSpace(code).toUpperCase();
    return mgrs.toPoint(cleaned); // → [lon, lat]
  } catch (e) {
    console.error('MGRS toPoint error', e);
    frappe.msgprint(__('Invalid MGRS code.'));
    return null;
  }
}

frappe.ui.form.on('Plantation Record', {
  refresh(frm) {
    // Bind once
    if (frm.__plant_sum_bound) return;
    frm.__plant_sum_bound = true;

    // Initial compute (if data pre-exists)
    recompute_and_format(frm);

    // Recompute when user edits grid cells
    const grid = frm.fields_dict.plantation_type_table && frm.fields_dict.plantation_type_table.grid;
    if (grid && grid.wrapper) {
      $(grid.wrapper)
        .off('.plant_sum')
        .on('keyup.plant_sum change.plant_sum',
          '[data-fieldname="no_of_plants"], [data-fieldname="acre"]',
          () => recompute_and_format(frm));
    }

    // Catch add/remove row
    frappe.ui.form.on('Plantation Record', {
      plantation_type_table_add:    f => recompute_and_format(f),
      plantation_type_table_remove: f => recompute_and_format(f),
    });
  },

  // If user edits totals manually, just normalize to Burmese digits
  total_plant(frm) { format_totals_only(frm); },
  total_area(frm)   { format_totals_only(frm); },

  validate(frm) {
    // Final normalization on save
    recompute_and_format(frm);
    format_totals_only(frm);
  }
});

/* ================= Core flow ================= */

function recompute_and_format(frm) {
  if (frm.__plant_sum_guard) return;
  frm.__plant_sum_guard = true;

  try {
    const rows = frm.doc.plantation_type_table || [];

    let allPlantsFilled = true;
    let allAcreFilled   = true;

    let totalPlants = 0;
    let totalAcre   = 0;

    rows.forEach(r => {
      // Normalize row values (accept Burmese/Arabic)
      const plantsNum = parse_mm_number(r.no_of_plants);
      const acreNum   = parse_mm_number(r.acre);

      // Detect completeness
      const hadPlants = has_any_digit(r.no_of_plants);
      const hadAcre   = has_any_digit(r.acre);
      if (!hadPlants) allPlantsFilled = false;
      if (!hadAcre)   allAcreFilled   = false;

      // Sum only numeric contributions
      if (isFinite(plantsNum)) totalPlants += plantsNum;
      if (isFinite(acreNum))   totalAcre   += acreNum;

      // Write back the row display in Burmese numerals
      const plantsDisplay = hadPlants && isFinite(plantsNum)
        ? to_mm_digits(String(Math.round(plantsNum)))
        : (hadPlants ? to_mm_digits(clean_numeric_string(r.no_of_plants)) : '');

      const acreDisplay = hadAcre && isFinite(acreNum)
        ? to_mm_digits(trim_trailing_zeros(acreNum.toFixed(2)))
        : (hadAcre ? to_mm_digits(clean_numeric_string(r.acre)) : '');

      safe_set_child_value(frm, r, 'no_of_plants', plantsDisplay);
      safe_set_child_value(frm, r, 'acre',         acreDisplay);
    });

    // Auto-fill totals only if column is fully filled in all rows
    if (rows.length && allPlantsFilled) {
      frm.set_value('total_plant', to_mm_digits(String(Math.round(totalPlants))));
    }
    if (rows.length && allAcreFilled) {
      frm.set_value('total_area', to_mm_digits(trim_trailing_zeros(totalAcre.toFixed(2))));
    }

    // If NOT fully filled, do NOT overwrite totals—user can input manually.
    // (We still format totals if they already exist and user typed them.)
    format_totals_only(frm);

  } finally {
    frm.__plant_sum_guard = false;
  }
}

/* ============ Total fields formatting only ============ */

function format_totals_only(frm) {
  // If user typed totals manually (Burmese or Arabic), just normalize to Burmese
  const tp_raw = String(frm.doc.total_plant || '');
  const ta_raw = String(frm.doc.total_area   || '');

  if (tp_raw) {
    const n = parse_mm_number(tp_raw);
    const formatted = isFinite(n) ? to_mm_digits(String(Math.round(n))) : to_mm_digits(clean_numeric_string(tp_raw));
    if (formatted !== frm.doc.total_plant) frm.set_value('total_plant', formatted);
  }

  if (ta_raw) {
    const n = parse_mm_number(ta_raw);
    const formatted = isFinite(n) ? to_mm_digits(trim_trailing_zeros(n.toFixed(2))) : to_mm_digits(clean_numeric_string(ta_raw));
    if (formatted !== frm.doc.total_area) frm.set_value('total_area', formatted);
  }
}

/* ============ Helpers ============ */

// Safe child set (works even before dt is present on the row)
function safe_set_child_value(frm, row, fieldname, value) {
  const dt = row.doctype || row.dt || guess_child_dt(frm, 'plantation_type_table');
  if (row.name && dt) {
    frappe.model.set_value(dt, row.name, fieldname, value);
  }
}

function guess_child_dt(frm, table_fieldname) {
  const df = frm.fields_dict[table_fieldname] && frm.fields_dict[table_fieldname].df;
  return df && df.options ? df.options : undefined; // options holds child DocType name
}

// Has any digit (Burmese or Arabic)
function has_any_digit(v) {
  if (!v && v !== 0) return false;
  const s = String(v);
  return /[0-9၀၁၂၃၄၅၆၇၈၉]/.test(s);
}

// Clean numeric-ish string: strip spaces/commas; keep dot and minus
function clean_numeric_string(v) {
  if (v == null) return '';
  let s = mm_to_ascii_digits(String(v));
  s = s.replace(/[,\s]/g, '');
  return s;
}

// Parse Burmese or Arabic numeric to Number; NaN if not parseable
function parse_mm_number(v) {
  if (v == null || v === '') return NaN;
  const s = clean_numeric_string(v);
  const n = parseFloat(s);
  return isNaN(n) ? NaN : n;
}

// Trim trailing zeros and dot ("12.50"->"12.5", "10.00"->"10")
function trim_trailing_zeros(s) {
  if (!s) return s;
  if (!s.includes('.')) return s;
  return s.replace(/\.?0+$/, '');
}

/* ============ Burmese digit conversion ============ */

// ASCII → Myanmar digits
function to_mm_digits(s) {
  if (s == null) return '';
  const map = {
    '0':'၀','1':'၁','2':'၂','3':'၃','4':'၄',
    '5':'၅','6':'၆','7':'၇','8':'၈','9':'၉','-':'-','+':'+','.':'.'
  };
  return String(s).split('').map(ch => map[ch] ?? ch).join('');
}

// Myanmar → ASCII digits (for parsing)
function mm_to_ascii_digits(s) {
  if (s == null) return '';
  const map = {
    '၀':'0','၁':'1','၂':'2','၃':'3','၄':'4',
    '၅':'5','၆':'6','၇':'7','၈':'8','၉':'9',
    '၊':',','။':'.'
  };
  return String(s).split('').map(ch => map[ch] ?? ch).join('');
}

frappe.ui.form.on('Annual Plantation Update', {
  refresh(frm) {
    // Bind a blur so copying happens as soon as you click away
    if (frm.__ps_blur_bound) return;
    frm.__ps_blur_bound = true;

    const fld = frm.fields_dict['plantation_serial'];
    if (fld && fld.$input) {
      fld.$input.off('blur.copy_ptt').on('blur.copy_ptt', () => {
        if (frm.doc.plantation_serial) frm.trigger('plantation_serial');
      });
    }
  },

  // Fires on commit/blur of plantation_serial
  plantation_serial(frm) {
    const recordName = frm.doc.plantation_serial;
    if (!recordName) return;

    // Only populate if target table is empty (avoid overwriting user edits)
    const alreadyHasRows = (frm.doc.plantation_type_table || []).length > 0;
    if (alreadyHasRows) return;

    copy_child_rows_from_plantation_record(frm, recordName);
  }
});

/* ---------------- Helpers ---------------- */

function copy_child_rows_from_plantation_record(frm, plantationRecordName) {
  if (frm.__ptt_copy_inflight) return;
  frm.__ptt_copy_inflight = true;

  frappe.call({
    method: 'frappe.client.get',
    args: { doctype: 'Plantation Record', name: plantationRecordName },
    callback: (r) => {
      frm.__ptt_copy_inflight = false;

      const doc = r && r.message;
      if (!doc) {
        frappe.msgprint(__('Could not fetch the selected Plantation Record.'));
        return;
      }

      const srcRows = doc.plantation_type_table || [];
      if (!srcRows.length) {
        frappe.msgprint(__('The selected Plantation Record has no rows in plantation_type_table.'));
        return;
      }

      // Determine child DocType (shared by both doctypes)
      const childFieldname = 'plantation_type_table';
      const childDt = get_child_dt(frm, childFieldname);
      if (!childDt) {
        frappe.msgprint(__('Cannot determine child table DocType for plantation_type_table.'));
        return;
      }

      // Build a safe copy field list from target child meta
      const targetFieldnames = get_copyable_child_fields(childDt);

      frm.clear_table(childFieldname);

      srcRows.forEach((srow) => {
        const d = frm.add_child(childFieldname);
        // Copy only fields that exist in the target child table
        targetFieldnames.forEach((f) => {
          if (Object.prototype.hasOwnProperty.call(srow, f)) {
            d[f] = srow[f]; // Works for Data and Link fields (uses the Link value/name)
          }
        });
      });

      frm.refresh_field(childFieldname);
      frappe.show_alert({ message: __('Plantation types copied from the selected Plantation Record.'), indicator: 'green' });
    },
    error: () => {
      frm.__ptt_copy_inflight = false;
      frappe.msgprint(__('Failed to fetch the Plantation Record. Check permissions/connection.'));
    }
  });
}

// Resolve child doctype from the field meta on this form
function get_child_dt(frm, table_fieldname) {
  const df = frm.fields_dict[table_fieldname] && frm.fields_dict[table_fieldname].df;
  return df && df.options ? df.options : undefined; // df.options holds the child DocType name
}

// Return fieldnames we’re allowed to copy (exclude system fields)
function get_copyable_child_fields(childDt) {
  const meta = frappe.get_meta(childDt);
  if (!meta || !meta.fields) return [];

  const deny = new Set(['name', 'owner', 'creation', 'modified', 'modified_by', 'parent', 'parenttype', 'parentfield', 'idx', 'doctype']);
  return meta.fields
    .map(f => f.fieldname)
    .filter(fn => fn && !deny.has(fn));
}

frappe.ui.form.on('Annual Plantation Update', {
  refresh(frm) {
    // Bind once
    if (frm.__plant_sum_bound) return;
    frm.__plant_sum_bound = true;

    // Initial compute (if data pre-exists)
    recompute_and_format(frm);

    // Recompute when user edits grid cells
    const grid = frm.fields_dict.plantation_type_table && frm.fields_dict.plantation_type_table.grid;
    if (grid && grid.wrapper) {
      $(grid.wrapper)
        .off('.plant_sum')
        .on('keyup.plant_sum change.plant_sum',
          '[data-fieldname="no_of_plants"], [data-fieldname="acre"]',
          () => recompute_and_format(frm));
    }

    // Catch add/remove row
    frappe.ui.form.on('Annual Plantation Update', {
      plantation_type_table_add:    f => recompute_and_format(f),
      plantation_type_table_remove: f => recompute_and_format(f),
    });
  },

  // If user edits totals manually, just normalize to Burmese digits
  total_plant(frm) { format_totals_only(frm); },
  total_area(frm)   { format_totals_only(frm); },

  validate(frm) {
    // Final normalization on save
    recompute_and_format(frm);
    format_totals_only(frm);
  }
});

/* ================= Core flow ================= */

function recompute_and_format(frm) {
  if (frm.__plant_sum_guard) return;
  frm.__plant_sum_guard = true;

  try {
    const rows = frm.doc.plantation_type_table || [];

    let allPlantsFilled = true;
    let allAcreFilled   = true;

    let totalPlants = 0;
    let totalAcre   = 0;

    rows.forEach(r => {
      // Normalize row values (accept Burmese/Arabic)
      const plantsNum = parse_mm_number(r.no_of_plants);
      const acreNum   = parse_mm_number(r.acre);

      // Detect completeness
      const hadPlants = has_any_digit(r.no_of_plants);
      const hadAcre   = has_any_digit(r.acre);
      if (!hadPlants) allPlantsFilled = false;
      if (!hadAcre)   allAcreFilled   = false;

      // Sum only numeric contributions
      if (isFinite(plantsNum)) totalPlants += plantsNum;
      if (isFinite(acreNum))   totalAcre   += acreNum;

      // Write back the row display in Burmese numerals
      const plantsDisplay = hadPlants && isFinite(plantsNum)
        ? to_mm_digits(String(Math.round(plantsNum)))
        : (hadPlants ? to_mm_digits(clean_numeric_string(r.no_of_plants)) : '');

      const acreDisplay = hadAcre && isFinite(acreNum)
        ? to_mm_digits(trim_trailing_zeros(acreNum.toFixed(2)))
        : (hadAcre ? to_mm_digits(clean_numeric_string(r.acre)) : '');

      safe_set_child_value(frm, r, 'no_of_plants', plantsDisplay);
      safe_set_child_value(frm, r, 'acre',         acreDisplay);
    });

    // Auto-fill totals only if column is fully filled in all rows
    if (rows.length && allPlantsFilled) {
      frm.set_value('total_plant', to_mm_digits(String(Math.round(totalPlants))));
    }
    if (rows.length && allAcreFilled) {
      frm.set_value('total_area', to_mm_digits(trim_trailing_zeros(totalAcre.toFixed(2))));
    }

    // If NOT fully filled, do NOT overwrite totals—user can input manually.
    // (We still format totals if they already exist and user typed them.)
    format_totals_only(frm);

  } finally {
    frm.__plant_sum_guard = false;
  }
}

/* ============ Total fields formatting only ============ */

function format_totals_only(frm) {
  // If user typed totals manually (Burmese or Arabic), just normalize to Burmese
  const tp_raw = String(frm.doc.total_plant || '');
  const ta_raw = String(frm.doc.total_area   || '');

  if (tp_raw) {
    const n = parse_mm_number(tp_raw);
    const formatted = isFinite(n) ? to_mm_digits(String(Math.round(n))) : to_mm_digits(clean_numeric_string(tp_raw));
    if (formatted !== frm.doc.total_plant) frm.set_value('total_plant', formatted);
  }

  if (ta_raw) {
    const n = parse_mm_number(ta_raw);
    const formatted = isFinite(n) ? to_mm_digits(trim_trailing_zeros(n.toFixed(2))) : to_mm_digits(clean_numeric_string(ta_raw));
    if (formatted !== frm.doc.total_area) frm.set_value('total_area', formatted);
  }
}

/* ============ Helpers ============ */

// Safe child set (works even before dt is present on the row)
function safe_set_child_value(frm, row, fieldname, value) {
  const dt = row.doctype || row.dt || guess_child_dt(frm, 'plantation_type_table');
  if (row.name && dt) {
    frappe.model.set_value(dt, row.name, fieldname, value);
  }
}

function guess_child_dt(frm, table_fieldname) {
  const df = frm.fields_dict[table_fieldname] && frm.fields_dict[table_fieldname].df;
  return df && df.options ? df.options : undefined; // options holds child DocType name
}

// Has any digit (Burmese or Arabic)
function has_any_digit(v) {
  if (!v && v !== 0) return false;
  const s = String(v);
  return /[0-9၀၁၂၃၄၅၆၇၈၉]/.test(s);
}

// Clean numeric-ish string: strip spaces/commas; keep dot and minus
function clean_numeric_string(v) {
  if (v == null) return '';
  let s = mm_to_ascii_digits(String(v));
  s = s.replace(/[,\s]/g, '');
  return s;
}

// Parse Burmese or Arabic numeric to Number; NaN if not parseable
function parse_mm_number(v) {
  if (v == null || v === '') return NaN;
  const s = clean_numeric_string(v);
  const n = parseFloat(s);
  return isNaN(n) ? NaN : n;
}

// Trim trailing zeros and dot ("12.50"->"12.5", "10.00"->"10")
function trim_trailing_zeros(s) {
  if (!s) return s;
  if (!s.includes('.')) return s;
  return s.replace(/\.?0+$/, '');
}

/* ============ Burmese digit conversion ============ */

// ASCII → Myanmar digits
function to_mm_digits(s) {
  if (s == null) return '';
  const map = {
    '0':'၀','1':'၁','2':'၂','3':'၃','4':'၄',
    '5':'၅','6':'၆','7':'၇','8':'၈','9':'၉','-':'-','+':'+','.':'.'
  };
  return String(s).split('').map(ch => map[ch] ?? ch).join('');
}

// Myanmar → ASCII digits (for parsing)
function mm_to_ascii_digits(s) {
  if (s == null) return '';
  const map = {
    '၀':'0','၁':'1','၂':'2','၃':'3','၄':'4',
    '၅':'5','၆':'6','၇':'7','၈':'8','၉':'9',
    '၊':',','။':'.'
  };
  return String(s).split('').map(ch => map[ch] ?? ch).join('');
}

// --- Helper: convert Myanmar digits → Latin (0-9) ---
function myanmar_to_latin(str) {
    var my = '၀၁၂၃၄၅၆၇၈၉';
    var en = '0123456789';

    if (!str) return '';

    return String(str).split('').map(function (ch) {
        var idx = my.indexOf(ch);
        return idx > -1 ? en[idx] : ch;
    }).join('');
}

// --- Helper: convert Latin digits → Myanmar digits ---
function latin_to_myanmar(str) {
    var my = '၀၁၂၃၄၅၆၇၈၉';
    var en = '0123456789';

    if (!str) return '';

    return String(str).split('').map(function (ch) {
        var idx = en.indexOf(ch);
        return idx > -1 ? my[idx] : ch;
    }).join('');
}

// --- Helper: extract starting year from fiscal year string ---
// e.g. "၂၀၂၁-၂၀၂၂" or "၂၀၁၉-၂၀၁၉ (mini)" → 2021 / 2019
function get_start_year_from_fy(fy_str) {
    if (!fy_str) return null;

    // Take everything before the first "-"
    var first_part = String(fy_str).split('-')[0].trim();   // "၂၀၂၁"
    var latin = myanmar_to_latin(first_part);               // "2021"
    var year = parseInt(latin, 10);

    if (isNaN(year)) {
        return null;
    }
    return year;
}

// --- Child table: only used when we really want to clear ---
function clear_work_done_table(frm) {
    frm.clear_table('maintenance_work');
    frm.refresh_field('maintenance_work');
}

// --- Child table: rebuild rows based on age (Latin integer) ---
// IMPORTANT: if user has already filled any detail fields, do NOT overwrite.
function rebuild_work_done_table(frm, age) {
    var rows = frm.doc.maintenance_work || [];

    // Check if there is any manual data we should respect
    var has_manual_data = (rows || []).some(function (row) {
        return (
            row.start_date ||
            row.end_date ||
            row.state_of_work_done ||
            row.rate_used ||
            row.total_expenditure
        );
    });

    // If user has already entered anything, don't touch their data
    if (has_manual_data) {
        return;
    }

    // If no manual data yet, it's safe to auto-generate
    frm.clear_table('maintenance_work');

    if (!age || age <= 0) {
        frm.refresh_field('maintenance_work');
        return;
    }

    var tasks = [];

    if (age === 1) {
        tasks = ['မြေတိုင်းတာခြင်း'];
    } else if (age === 2 || age === 3 || age === 4) {
        tasks = [
            'ပေါင်းသင်ရှင်းခြင်း',
            'သေပင်ဖာထေးခြင်း',
            'မီးကာကွယ်ခြင်း'
        ];
    } else if (age === 5) {
        tasks = ['မီးကာကွယ်ခြင်း'];
    } else if (age >= 6 && age <= 30) {
        tasks = [
        'ပင်ကျပ်နုတ်ခြင်း',
        'ပင်ပူးခွာကိုင်းချိုင်ရှင်းလင်းခြင်း'];
    } else {
        // age > 30 → no auto rows
        tasks = [];
    }

    tasks.forEach(function(task) {
        var row = frm.add_child('maintenance_work');
        // start_date / end_date / state_of_work_done / rate_used / total_expenditure
        // left empty for user to fill manually
        row.work_done = task;
    });

    frm.refresh_field('maintenance_work');
}

// --- Main age calculation + child-table update ---
function update_age_of_plantation(frm) {
    var fy_name = frm.doc.fiscal_year_name;            // e.g. "၂၀၂၁-၂၀၂၂"
    var est_year_str = frm.doc.year_of_establishment; // e.g. "၂၀၂၀-၂၀၂၁"

    var fy_start = get_start_year_from_fy(fy_name);
    var est_start = get_start_year_from_fy(est_year_str);

    // If either side is missing or invalid, clear age & child table
    if (!fy_start || !est_start) {
        frm.set_value('age_of_plantation', '');
        clear_work_done_table(frm);
        return;
    }

    // Age formula:
    // same year → 1
    // e.g. fy 2021-2022, est 2020-2021 → (2021 - 2020) + 1 = 2
    var age = (fy_start - est_start) + 1;

    // If establishment is after fiscal year, don’t show a negative/zero age
    if (age <= 0) {
        frm.set_value('age_of_plantation', '');
        clear_work_done_table(frm);
        return;
    }

    // Save age in Myanmar digits
    var age_myanmar = latin_to_myanmar(age.toString());
    frm.set_value('age_of_plantation', age_myanmar);

    // Update child table based on numeric age (but only if still "clean")
    rebuild_work_done_table(frm, age);
}

