/* =============== Blur binding (original) =============== */

function bind_blur_handlers(frm) {
  // Latitude
  const latField = frm.fields_dict['latitude'];
  if (latField && latField.$input) {
    latField.$input.off('blur.dms_lat').on('blur.dms_lat', () => {
      if (!frm.__coord_updating) syncFromLatLng(frm);
    });
  }

  // Longitude
  const lonField = frm.fields_dict['longitude'];
  if (lonField && lonField.$input) {
    lonField.$input.off('blur.dms_lon').on('blur.dms_lon', () => {
      if (!frm.__coord_updating) syncFromLatLng(frm);
    });
  }

  // MGRS
  const mgrsField = frm.fields_dict['mgrs'];
  if (mgrsField && mgrsField.$input) {
    mgrsField.$input.off('blur.dms_mgrs').on('blur.dms_mgrs', () => {
      if (!frm.__coord_updating) syncFromMGRS(frm);
    });
  }
}

/* =============== Utilities (original) =============== */

function setValueQuiet(frm, fieldname, value) {
  frm.__coord_updating = true;
  frm.set_value(fieldname, value);
  frm.__coord_updating = false;
}

function whenMgrsReady(cb, tries = 40) { // ~10s
  if (typeof mgrs !== 'undefined') return cb();
  if (tries <= 0) return;
  setTimeout(() => whenMgrsReady(cb, tries - 1), 250);
}

// NEW: wait for Google + mgrs
function whenMapsAndMgrsReady(cb, tries = 40) {
  if (typeof google !== 'undefined' && google.maps && typeof mgrs !== 'undefined') {
    return cb();
  }
  if (tries <= 0) return;
  setTimeout(() => whenMapsAndMgrsReady(cb, tries - 1), 250);
}

function noSpace(v)    { return (v || '').toString().replace(/\s+/g, ''); }
function getVal(v)     { return v == null ? '' : String(v); }
function isFiniteStr(v){ return typeof v === 'number' ? isFinite(v) : /^[-+]?\d+(\.\d+)?$/.test(v); }

/* =============== Core flows (run only on blur/validate) =============== */

function syncFromLatLng(frm) {
  const latRaw = noSpace(getVal(frm.doc.latitude));
  const lonRaw = noSpace(getVal(frm.doc.longitude));
  if (!latRaw || !lonRaw) {
    // If one side missing, just clean the edited one
    if (latRaw) setValueQuiet(frm, 'latitude', latRaw);
    if (lonRaw) setValueQuiet(frm, 'longitude', lonRaw);
    return;
  }

  const parsed = parseLatLonFlexible(latRaw, lonRaw);
  if (!parsed) {
    setValueQuiet(frm, 'latitude',  latRaw);
    setValueQuiet(frm, 'longitude', lonRaw);
    return;
  }

  const dmsLat = toDMS(parsed.lat, true);
  const dmsLon = toDMS(parsed.lon, false);
  setValueQuiet(frm, 'latitude',  dmsLat);
  setValueQuiet(frm, 'longitude', dmsLon);

  // Compute MGRS after user leaves the field
  whenMgrsReady(() => {
    const m = safeMgrsForward(parsed.lat, parsed.lon, 3); // 6-digit (~100 m)
    if (m) setValueQuiet(frm, 'mgrs', m);
    // Update map too
    updateMapFromDoc(frm);
  });
}

function syncFromMGRS(frm) {
  const mgrsRaw = noSpace(getVal(frm.doc.mgrs)).toUpperCase();
  if (!mgrsRaw) return;

  whenMgrsReady(() => {
    const pt = safeMgrsToPoint(mgrsRaw);
    if (pt) {
      const [lonDec, latDec] = pt;
      setValueQuiet(frm, 'latitude',  toDMS(latDec, true));
      setValueQuiet(frm, 'longitude', toDMS(lonDec, false));
      setValueQuiet(frm, 'mgrs',      mgrsRaw);
      updateMapFromDoc(frm);
    } else {
      setValueQuiet(frm, 'mgrs', mgrsRaw); // keep cleaned value even if invalid
    }
  });
}

function normalizeAll(frm) {
  const lat = noSpace(getVal(frm.doc.latitude));
  const lon = noSpace(getVal(frm.doc.longitude));
  const mg  = noSpace(getVal(frm.doc.mgrs)).toUpperCase();

  if (!lat && !lon && !mg) return;

  if (lat && lon) {
    const parsed = parseLatLonFlexible(lat, lon);
    if (parsed) {
      setValueQuiet(frm, 'latitude',  toDMS(parsed.lat, true));
      setValueQuiet(frm, 'longitude', toDMS(parsed.lon, false));
      whenMgrsReady(() => {
        const m = safeMgrsForward(parsed.lat, parsed.lon, 3);
        if (m) setValueQuiet(frm, 'mgrs', m);
        updateMapFromDoc(frm);
      });
    } else {
      setValueQuiet(frm, 'latitude', lat);
      setValueQuiet(frm, 'longitude', lon);
    }
  } else if (mg) {
    whenMgrsReady(() => {
      const pt = safeMgrsToPoint(mg);
      if (pt) {
        const [lonDec, latDec] = pt;
        setValueQuiet(frm, 'latitude',  toDMS(latDec, true));
        setValueQuiet(frm, 'longitude', toDMS(lonDec, false));
        updateMapFromDoc(frm);
      }
      setValueQuiet(frm, 'mgrs', mg);
    });
  }
}

/* =============== Parsing & formatting (original) =============== */

// Accepts decimal or DMS strings for both fields
function parseLatLonFlexible(latIn, lonIn) {
  try {
    const lat = parseOne(latIn, true);
    const lon = parseOne(lonIn, false);
    if (!isFinite(lat) || !isFinite(lon)) return null;
    if (Math.abs(lat) > 90 || Math.abs(lon) > 180) return null;
    return { lat, lon };
  } catch {
    return null;
  }
}

function parseOne(value, isLat) {
  if (value == null || value === '') return NaN;
  if (isFiniteStr(value)) return parseFloat(value); // decimal degrees
  const d = dmsToDecimal(value, isLat);             // DMS → decimal
  if (d == null) throw new Error('Bad DMS');
  return d;
}

// Robust DMS parser → decimal degrees
function dmsToDecimal(dmsStr, isLat) {
  if (!dmsStr) return null;

  // Canonicalize symbols WITHOUT touching hemisphere letters
  // Replace "deg"/"º"/"°" → "°" only (don't replace 'E'!)
  let s = dmsStr.toUpperCase();
  s = s.replace(/\s+/g, '');
  s = s.replace(/DEG/gi, '°').replace(/º/g, '°');  // "deg" or "º" → "°"
  s = s.replace(/[’']/g, "'");                      // apostrophes
  s = s.replace(/″|”/g, '"');                       // double-primes

  // [opt hem] deg° [opt min]' [opt sec]" [opt hem]
  const re = /^(?:([NSWE]))?(\d+(?:\.\d+)?)°(?:(\d+(?:\.\d+)?))?'?(?:(\d+(?:\.\d+)?))?"?(?:([NSWE]))?$/;
  const m = s.match(re);
  if (!m) return null;

  let hem = (m[1] || m[5] || '').toUpperCase();
  const deg = parseFloat(m[2] || '0');
  const min = parseFloat(m[3] || '0');
  const sec = parseFloat(m[4] || '0');

  if (!hem) hem = isLat ? 'N' : 'E';         // default if hemisphere not provided
  if (min >= 60 || sec >= 60) return null;
  if (isLat && deg > 90) return null;
  if (!isLat && deg > 180) return null;

  let dec = deg + min / 60 + sec / 3600;
  if ((isLat && hem === 'S') || (!isLat && hem === 'W')) dec = -dec;
  return dec;
}

function toDMS(dec, isLat) {
  const hemi = isLat ? (dec >= 0 ? 'N' : 'S') : (dec >= 0 ? 'E' : 'W');
  const abs = Math.abs(dec);
  const deg = Math.floor(abs);
  const minFloat = (abs - deg) * 60;
  const min = Math.floor(minFloat);
  const sec = (minFloat - min) * 60;
  const secFixed = sec.toFixed(2);
  return `${deg}°${String(min).padStart(2, '0')}'${padSec(secFixed)}"${hemi}`;
}

function padSec(secStr) {
  if (!secStr.includes('.')) return secStr.padStart(2, '0');
  const [i, f] = secStr.split('.');
  return `${i.padStart(2, '0')}.${f}`;
}

/* =============== MGRS helpers (original) =============== */

function safeMgrsForward(lat, lon, precision = 3) {
  try {
    // mgrs.forward expects [lon, lat]
    const s = mgrs.forward([lon, lat], precision);
    return noSpace(s).toUpperCase();
  } catch (e) {
    console.error('MGRS forward error', e);
    frappe.msgprint(__('Unable to calculate MGRS from coordinates.'));
    return '';
  }
}

function safeMgrsToPoint(code) {
  try {
    const cleaned = noSpace(code).toUpperCase();
    return mgrs.toPoint(cleaned); // → [lon, lat]
  } catch (e) {
    console.error('MGRS toPoint error', e);
    frappe.msgprint(__('Invalid MGRS code.'));
    return null;
  }
}

/* =============== MAP HELPERS (NEW) =============== */

function computeLatLngFromDoc(frm) {
  const latRaw = noSpace(getVal(frm.doc.latitude));
  const lonRaw = noSpace(getVal(frm.doc.longitude));
  const mg     = noSpace(getVal(frm.doc.mgrs)).toUpperCase();

  // 1) Prefer MGRS if available
  if (mg) {
    const pt = safeMgrsToPoint(mg);
    if (pt) {
      const [lonDec, latDec] = pt;
      return { lat: latDec, lon: lonDec };
    }
  }

  // 2) Fallback to lat/long (DMS or decimal)
  if (latRaw && lonRaw) {
    const parsed = parseLatLonFlexible(latRaw, lonRaw);
    if (parsed) return { lat: parsed.lat, lon: parsed.lon };
  }

  return null;
}

function initializeOrUpdateMap(frm) {
  const mapDiv = document.getElementById('plantation-map');
  if (!mapDiv) {
    console.error('Map container not found');
    return;
  }

  const defaultCenter = { lat: 19.8244, lon: 96.1296 }; // Myanmar-ish
  const target = computeLatLngFromDoc(frm) || defaultCenter;
  const center = { lat: target.lat, lng: target.lon };

  if (!frm.__plantation_map) {
    frm.__plantation_map = new google.maps.Map(mapDiv, {
      center,
      zoom: 13,
    });

    frm.__plantation_marker = new google.maps.Marker({
      position: center,
      map: frm.__plantation_map,
    });
  } else {
    frm.__plantation_map.setCenter(center);
    frm.__plantation_marker.setPosition(center);
  }
}

function updateMapFromDoc(frm) {
  if (!frm.__plantation_map || !frm.__plantation_marker) return;
  const target = computeLatLngFromDoc(frm);
  if (!target) return;
  const center = { lat: target.lat, lng: target.lon };
  frm.__plantation_map.setCenter(center);
  frm.__plantation_marker.setPosition(center);
}
